-- ADDITIONAL ADJUSTMENTS TO DIAGNOSTICO
UPDATE diagnostico d 
SET codigo_icd10cm = 'F45.21'
WHERE nombre = 'Trastorno de ansiedad por enfermedad';

UPDATE diagnostico d 
SET nombre = 'Trastorno facticio impuesto a sí mismo, no especificado'
WHERE nombre = 'Trastorno facticio'
AND codigo_icd10cm = 'F68.10';

-- CLEAN CRITERIO CLINICO AND CRITERIO CLINICO CATEGORY
DELETE FROM sesion_criterio_clinico WHERE id > 0;
DELETE FROM criterio_clinico WHERE id > 0;
DELETE FROM categoria_criterio_clinico WHERE id > 0;

-- SEED CRITERIO CLINICO CATALOG
INSERT INTO categoria_criterio_clinico (nombre, descripcion, estado_id) VALUES
('Sueño y vigilia', 'Criterios relacionados con la cantidad, calidad, continuidad y regulación del sueño y la vigilia, incluyendo alteraciones del inicio o mantenimiento del sueño, despertares y somnolencia.', 1),
('Atención y funciones ejecutivas', 'Criterios relacionados con la capacidad para mantener la atención, organizar actividades, planificar, inhibir respuestas, gestionar el tiempo, seguir instrucciones y regular la conducta dirigida a objetivos.', 1),
('Acumulación', 'Criterios relacionados con la dificultad persistente para descartar o desprenderse de objetos, independientemente de su valor, debido a una necesidad percibida de conservarlos.', 1),
('Síntomas físicos y somáticos', 'Criterios relacionados con síntomas corporales, sensaciones físicas y preocupaciones persistentes sobre la salud o el funcionamiento físico que generan malestar o deterioro significativo.', 1),
('Agresión y conducta destructiva', 'Criterios relacionados con comportamientos agresivos, amenazas, intimidación, destrucción de propiedad u otras conductas dirigidas a causar daño a personas, animales u objetos.', 1),
('Conductas repetitivas', 'Criterios relacionados con comportamientos, movimientos o acciones que se realizan de manera repetitiva y persistente, con o sin una finalidad aparente.', 1),
('Conductas centradas en el cuerpo', 'Criterios relacionados con comportamientos repetitivos dirigidos hacia el propio cuerpo, como arrancarse el cabello, lesionarse la piel u otras conductas similares.', 1),
('Estado de ánimo y afectividad', 'Criterios relacionados con el estado emocional, incluyendo tristeza, irritabilidad, euforia, disminución del interés o placer, cambios afectivos y alteraciones persistentes del estado de ánimo.', 1),
('Síntomas psicóticos','Criterios relacionados con alteraciones de la percepción, pensamiento y juicio de realidad, incluyendo delirios, alucinaciones, pensamiento desorganizado y otros síntomas psicóticos.',1),
('Ansiedad de separación y apego','Criterios relacionados con temor o malestar excesivo ante la separación de figuras de apego, preocupación por su pérdida y dificultades asociadas con la separación o la necesidad de proximidad.',1),
('Sexualidad','Criterios relacionados con el funcionamiento, interés, respuesta y comportamiento sexual cuando presentan alteraciones clínicamente significativas o generan malestar o deterioro funcional.',1),
('Ansiedad','Criterios relacionados con preocupación, temor, tensión, inquietud y respuestas fisiológicas asociadas con situaciones percibidas como amenazantes o inciertas.',1),
('Lenguaje y comunicación','Criterios relacionados con la adquisición, comprensión, expresión y uso funcional del lenguaje y de las habilidades necesarias para la comunicación.',1),
('Percepción e imagen corporal','Criterios relacionados con la percepción, valoración y preocupación respecto al propio cuerpo, apariencia física o características corporales.',1),
('Alimentación','Criterios relacionados con los patrones de alimentación, ingesta, evitación o restricción de alimentos y otras conductas alimentarias que pueden producir consecuencias clínicas o deterioro funcional.',1),
('Conducta disocial','Criterios relacionados con patrones persistentes de comportamiento que vulneran derechos de otras personas, normas sociales o reglas apropiadas para la edad.',1),
('Habla y fluidez','Criterios relacionados con la producción del habla, su fluidez, ritmo y continuidad, incluyendo alteraciones que interfieren con la comunicación efectiva.',1),
('Pensamientos intrusivos y rituales','Criterios relacionados con pensamientos, impulsos o imágenes recurrentes e intrusivos y con conductas o actos mentales repetitivos realizados para reducir la ansiedad o prevenir determinados acontecimientos.',1),
('Conducta','Criterios relacionados con patrones observables de comportamiento, autorregulación, control de impulsos y respuestas conductuales que pueden generar malestar o deterioro en diferentes contextos.',1),
('Cognición y aprendizaje','Criterios relacionados con procesos cognitivos y habilidades académicas, incluyendo adquisición, comprensión, razonamiento, memoria y desempeño en áreas específicas del aprendizaje.',1),
('Trauma y disociación','Criterios relacionados con la exposición a acontecimientos traumáticos o estresantes y con respuestas posteriores que pueden incluir reexperimentación, evitación, alteraciones emocionales, hiperactivación o síntomas disociativos.',1),
('Funcionamiento adaptativo y social','Criterios relacionados con la capacidad para desenvolverse de manera autónoma y efectiva en actividades cotidianas, relaciones interpersonales, comunicación y participación social.',1),
('Coordinación motora','Criterios relacionados con la adquisición y ejecución de habilidades motoras, coordinación, precisión y desempeño de actividades que requieren control y planificación motora.',1),
('Expresión escrita','Criterios relacionados con la adquisición y utilización de habilidades de escritura, incluyendo ortografía, expresión escrita, organización y producción de textos.',1),
('Eliminación','Criterios relacionados con la eliminación involuntaria o voluntaria de orina o heces en lugares inapropiados, considerando la edad y el nivel de desarrollo esperado.',1),
('Miedo y evitación','Criterios relacionados con temor intenso o persistente ante objetos, situaciones o circunstancias específicas y con conductas de evitación o resistencia asociadas.',1),
('Procesamiento sensorial','Criterios relacionados con la respuesta y sensibilidad ante estímulos sensoriales, incluyendo hiperreactividad, hiporreactividad o búsqueda inusual de estimulación sensorial.',1),
('Riesgo y seguridad','Criterios relacionados con conductas, pensamientos o circunstancias que pueden representar riesgo para la integridad física propia o de otras personas y con la necesidad de valorar medidas de seguridad.',1),
('Desarrollo','Criterios relacionados con la adquisición y evolución de habilidades esperadas durante el desarrollo, considerando la edad, el nivel de funcionamiento y posibles retrasos o desviaciones del desarrollo.',1);


-- DROP CODIGO COLUMN
ALTER TABLE public.criterio_clinico
DROP COLUMN codigo;

-- SEED CRITERIO CLINICO
