    c.id,
    v.nombre,
    v.descripcion,
    1
FROM (
    VALUES
        ('Sueño y vigilia', 'Activación autonómica', 'Sensaciones físicas como aumento del ritmo cardíaco, sudoración, temblor o respiración acelerada asociadas al sueño o al despertar.'),
        ('Atención y funciones ejecutivas', 'Actúa como si estuviera impulsado por un motor', 'El paciente presenta una necesidad constante de moverse o dificultad para permanecer quieto, como si tuviera una energía motora excesiva.'),
        ('Acumulación', 'Acumulación excesiva', 'Dificultad persistente para desprenderse de objetos, independientemente de su valor real o utilidad.'),
        ('Síntomas físicos y somáticos', 'Agitación o enlentecimiento psicomotor', 'Se observa aumento notable de la actividad motora o, por el contrario, movimientos y respuestas físicas considerablemente lentos.'),
        ('Agresión y conducta destructiva', 'Agresión', 'Conductas dirigidas a causar daño físico, verbal o psicológico a otra persona, animal u objeto.'),
